// Why: The accumulator starts as {} and must be returned from every callback. Create the
// category's array the first time you see it, then push.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/reduce
function groupByCategory(items) {
  return items.reduce((groups, item) => {
    if (!groups[item.category]) groups[item.category] = [];
    groups[item.category].push(item.name);
    return groups;
  }, {});
}

